def gen(rng):
    def case(w):
        return f'{len(w)}\n' + ' '.join(map(str, w))

    def fmt(cases):
        return str(len(cases)) + '\n' + '\n'.join(cases)

    tests = [fmt([case([3, 3, 7, 3, 1]), case([10, 11, 7, 7, 7]), case([1, 1, 8, 1, 1, 1]), case([3, 2, 4, 2, 5])]),
             fmt([case([5])]), fmt([case([1, 1])]), fmt([case([1, 2])]), fmt([case([5000, 1])]), fmt([case([2, 2, 3, 4, 5])]),
             fmt([case([2, 2, 2, 3, 7])]), fmt([case([1] * 7)]), fmt([case([4, 4, 4])]), fmt([case([7, 7, 7, 7, 1])])]
    for _ in range(14):
        cs = []
        for _ in range(rng.randint(1, 4)):
            n = rng.randint(1, 9)
            hi = rng.choice([5, 10, 30, 5000])
            cs.append(case([rng.randint(1, hi) for _ in range(n)]))
        tests.append(fmt(cs))
    for hi in (5000, 5000, 100, 5000):
        tests.append(fmt([case([rng.randint(1, hi) for _ in range(50)]) for _ in range(50)]))
    tests.append(fmt([case([5000] * 49 + [4999]) for _ in range(50)]))
    tests.append(fmt([case([rng.randint(4500, 5000) for _ in range(50)]) for _ in range(50)]))
    return tests

